    """Create ZIP/TAR and optional stream layers. Returns output path.

    ``formats`` are ordered inner-to-outer, e.g. ["tar", "gz"].
    """
    formats = [str(x).lower().lstrip(".") for x in (formats or [])]
    aliases = {"tgz": ["tar", "gz"], "tbz": ["tar", "bz2"],
               "tbz2": ["tar", "bz2"], "txz": ["tar", "xz"],
               "tlzma": ["tar", "lzma"], "tzst": ["tar", "zst"],
               "tlz": ["tar", "lz"], "tlz4": ["tar", "lz4"],
               "tsz": ["tar", "sz"], "cbz": ["zip"], "epub": ["zip"],
               "cb7": ["7z"]}
    if len(formats) == 1 and formats[0] in aliases:
        formats = aliases[formats[0]]
    if not formats:
        raise ValueError("compression format required")
    if formats[0] not in ("zip", "tar"):
        if formats[0] in ("gz", "bz", "bz2", "xz", "lzma") and len(inputs) == 1:
            source = os.fspath(inputs[0])
            level = 9 if level is None else max(0, min(9, int(level)))
            with open(source, "rb") as inp, open(output, "wb") as raw:
                if formats[0] == "gz":
                    with gzip.GzipFile(filename="", mode="wb", compresslevel=max(1, level), fileobj=raw, mtime=0) as enc:
                        _copy(inp, enc)
                elif formats[0] in ("bz", "bz2"):
                    raw.write(bz2.compress(inp.read(), compresslevel=max(1, min(9, level))))
                elif formats[0] in ("xz", "lzma"):
                    raw.write(lzma.compress(inp.read(), preset=max(0, min(9, level))))
            return output
        raise ValueError("unsupported compression format")
    if formats[0] == "zip":
        comp = zipfile.ZIP_DEFLATED
        with zipfile.ZipFile(output, "w", comp, compresslevel=level) as zf:
            for src, arc in _members(inputs):
                if os.path.isdir(src):
                    zf.write(src, arc.rstrip("/") + "/")
                elif follow_symlinks or not os.path.islink(src):
                    zf.write(src, arc)
